package ir.neshane.isolationprobe.operations;

import static ir.neshane.isolationprobe.operations.LabOperationsTrust.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** Each instance connects only to its owner's database; no cross-service SQL. */
final class DurableOperationStore {
    private final Path bootstrap;
    final String cell;
    final long boot;
    volatile boolean quarantined;
    DurableOperationStore(Path bootstrap,String cell)throws Exception{this.bootstrap=bootstrap;this.cell=cell;long epoch=0;try(var c=connect()){check(c);c.setAutoCommit(false);row(c,true);try(var p=c.prepareStatement("UPDATE oref.meta SET boot_epoch=boot_epoch+1 RETURNING boot_epoch")){try(var r=p.executeQuery()){r.next();epoch=r.getLong(1);}}c.commit();}catch(Exception failure){quarantined=true;System.out.println("STORE_QUARANTINED "+safe(failure));}boot=epoch;}
    Connection connect()throws Exception{var p=new Properties();p.setProperty("user",Files.readString(bootstrap.resolve("db.user")).strip());p.setProperty("password",Files.readString(bootstrap.resolve("db.pass")).strip());p.setProperty("sslmode","verify-full");p.setProperty("sslrootcert",bootstrap.resolve("pg-root.pem").toString());p.setProperty("connectTimeout","3");p.setProperty("socketTimeout","10");p.setProperty("ApplicationName","oref-"+cell);return DriverManager.getConnection("jdbc:postgresql://operations-state:5432/"+Files.readString(bootstrap.resolve("db.name")).strip(),p);}
    void check(Connection c)throws Exception{
        require(!quarantined,"QUARANTINED");try(var s=c.createStatement();var r=s.executeQuery("SELECT store_id,pg_start,quarantined,pg_postmaster_start_time()::text,(SELECT count(*) FROM oref.commands WHERE state='COMMITTED'),commit_seq,(SELECT count(*) FROM oref.effects),(SELECT count(*) FROM oref.outbox) FROM oref.meta")){require(r.next(),"STORE_META_MISSING");require(r.getString(1).equals(Files.readString(bootstrap.resolve("store.id")).strip()),"STORE_ID_CHANGED");require(r.getString(2).equals(r.getString(4))&&r.getString(4).equals(Files.readString(bootstrap.resolve("pg.start")).strip()),"PG_INCARNATION_CHANGED");require(!r.getBoolean(3),"QUARANTINED");require(r.getLong(5)==r.getLong(6)&&r.getLong(6)==r.getLong(7)&&r.getLong(7)==r.getLong(8),"DURABILITY_INVARIANT");}catch(Exception failure){quarantined=true;throw failure;}}
    Map<String,String> row(Connection c,boolean lock)throws Exception{try(var s=c.createStatement();var r=s.executeQuery("SELECT boot_epoch,fence,policy,tenant,cell FROM oref.meta"+(lock?" FOR UPDATE":""))){require(r.next(),"STORE_META_MISSING");return map("boot",""+r.getLong(1),"fence",""+r.getLong(2),"policy",""+r.getLong(3),"tenant",r.getString(4),"cell",r.getString(5));}}
    Map<String,String> metadata()throws Exception{try(var c=connect()){check(c);var m=row(c,false);m.put("code","OK");return m;}}
    void register(Map<String,String> command)throws Exception{String body=packed(command),digest=hash(bytes(command));try(var c=connect();var p=c.prepareStatement("INSERT INTO oref.grants(command_id,semantic_hash,body,state) VALUES (?,?,?,'ACTIVE')")){check(c);p.setString(1,command.get("command-id"));p.setString(2,digest);p.setString(3,body);p.executeUpdate();}}
    Map<String,String> grant(String id)throws Exception{try(var c=connect();var p=c.prepareStatement("SELECT body,state,epoch,semantic_hash FROM oref.grants WHERE command_id=?")){check(c);p.setString(1,id);try(var r=p.executeQuery()){require(r.next(),"APPROVAL_MISSING");return map("body",r.getString(1),"state",r.getString(2),"epoch",""+r.getLong(3),"hash",r.getString(4));}}}
    void grantState(String id,String state)throws Exception{try(var c=connect();var p=c.prepareStatement("UPDATE oref.grants SET state=?,epoch=epoch+1 WHERE command_id=? AND state<>'REVOKED'")){check(c);p.setString(1,state);p.setString(2,id);require(p.executeUpdate()==1,"GRANT_STATE_CONFLICT");}}
    void revoke(String id,long epoch)throws Exception{try(var c=connect()){c.setAutoCommit(false);row(c,true);try(var p=c.prepareStatement("INSERT INTO oref.revocations(command_id,epoch) VALUES (?,?) ON CONFLICT DO NOTHING")){p.setString(1,id);p.setLong(2,epoch);p.executeUpdate();}try(var s=c.createStatement()){s.executeUpdate("UPDATE oref.meta SET fence=fence+1");}c.commit();}}
    void advance(String field)throws Exception{require(Set.of("fence","policy","boot_epoch").contains(field),"FIELD_ALLOWLIST");try(var c=connect()){c.setAutoCommit(false);row(c,true);try(var s=c.createStatement()){s.executeUpdate("UPDATE oref.meta SET "+field+"="+field+"+1");}c.commit();}}
    void revokePeer(String fingerprint)throws Exception{require(fingerprint.matches("[a-f0-9]{64}"),"FINGERPRINT_FORMAT");try(var c=connect();var p=c.prepareStatement("INSERT INTO oref.peer_revocations(fingerprint) VALUES (?) ON CONFLICT DO NOTHING")){check(c);p.setString(1,fingerprint);p.executeUpdate();}}
    Set<String> revokedPeers()throws Exception{var peers=new HashSet<String>();try(var c=connect();var s=c.createStatement();var r=s.executeQuery("SELECT fingerprint FROM oref.peer_revocations")){while(r.next())peers.add(r.getString(1));}return peers;}
    Map<String,String> prepared(Map<String,String> g,String semantic)throws Exception{try(var c=connect()){c.setAutoCommit(false);check(c);var meta=row(c,true);require(meta.get("boot").equals(""+boot),"BOOT_FENCED");try(var p=c.prepareStatement("SELECT semantic_hash,state,outcome FROM oref.commands WHERE command_id=?")){p.setString(1,g.get("command-id"));try(var r=p.executeQuery()){if(r.next()){require(r.getString(1).equals(semantic),"COMMAND_ID_CONFLICT");if(r.getString(2).equals("COMMITTED")){var result=unpack(r.getString(3));result.put("duplicate","true");c.rollback();return result;}}}}try(var p=c.prepareStatement("INSERT INTO oref.commands(command_id,semantic_hash,tenant,cell,state,boot_epoch) VALUES (?,?,?,?,'PREPARED',?) ON CONFLICT DO NOTHING")){p.setString(1,g.get("command-id"));p.setString(2,semantic);p.setString(3,g.get("tenant"));p.setString(4,g.get("cell"));p.setLong(5,boot);p.executeUpdate();}c.commit();return map("code","PREPARED","fence",meta.get("fence"),"policy",meta.get("policy"));}}
    @FunctionalInterface interface Boundary { void await(String stage)throws Exception; }
    Map<String,String> effect(Map<String,String> g,String semantic,Map<String,String> prepared,java.util.function.LongSupplier limitingClock,Boundary boundary)throws Exception{
        try(var c=connect()){c.setAutoCommit(false);check(c);var meta=row(c,true);require(meta.get("boot").equals(""+boot),"BOOT_FENCED");require(meta.get("tenant").equals(g.get("tenant"))&&meta.get("cell").equals(g.get("cell")),"STORE_SCOPE");require(meta.get("fence").equals(prepared.get("fence"))&&meta.get("policy").equals(prepared.get("policy"))&&meta.get("policy").equals(g.get("policy")),"FENCE_OR_POLICY_CHANGED");
            try(var p=c.prepareStatement("SELECT 1 FROM oref.revocations WHERE command_id=?")){p.setString(1,g.get("command-id"));try(var r=p.executeQuery()){require(!r.next(),"LOCALLY_REVOKED");}}
            try(var p=c.prepareStatement("SELECT semantic_hash,state,outcome FROM oref.commands WHERE command_id=? FOR UPDATE")){p.setString(1,g.get("command-id"));try(var r=p.executeQuery()){require(r.next()&&r.getString(1).equals(semantic),"COMMAND_ID_CONFLICT");if(r.getString(2).equals("COMMITTED")){var result=unpack(r.getString(3));result.put("duplicate","true");c.rollback();return result;}}}
            require(meta.get("fence").equals(g.get("fence")),"SIGNED_FENCE_SUPERSEDED");long now;try(var s=c.createStatement();var r=s.executeQuery("SELECT (extract(epoch FROM clock_timestamp())*1000)::bigint")){r.next();now=Math.max(r.getLong(1),limitingClock.getAsLong());}require(now>=Long.parseLong(g.get("not-before"))&&now<Long.parseLong(g.get("expires")),"GRANT_EXPIRED_AT_EFFECT");
            String digest=hash(g.get("value").getBytes(java.nio.charset.StandardCharsets.UTF_8));require(digest.equals(g.get("content-digest")),"CONTENT_SUBSTITUTION");long version;
            try(var p=c.prepareStatement("UPDATE oref.resources SET version=version+1,value=?,digest=? WHERE resource_id=? AND version=? AND service=? AND tenant=? AND cell=? RETURNING version")){p.setString(1,g.get("value"));p.setString(2,digest);p.setString(3,g.get("resource"));p.setLong(4,Long.parseLong(g.get("expected-version")));p.setString(5,g.get("service"));p.setString(6,g.get("tenant"));p.setString(7,g.get("cell"));try(var r=p.executeQuery()){require(r.next(),"RESOURCE_VERSION_CONFLICT");version=r.getLong(1);}}
            long seq;try(var s=c.createStatement();var r=s.executeQuery("UPDATE oref.meta SET commit_seq=commit_seq+1 RETURNING commit_seq")){r.next();seq=r.getLong(1);}var result=map("code","OK","id",g.get("command-id"),"cell",cell,"tenant",g.get("tenant"),"resource",g.get("resource"),"version",""+version,"seq",""+seq,"semantic-hash",semantic,"digest",digest,"duplicate","false");
            try(var p=c.prepareStatement("INSERT INTO oref.effects VALUES (?,?,?,?,?,?,?,?,?)")){p.setLong(1,seq);p.setString(2,g.get("command-id"));p.setString(3,g.get("tenant"));p.setString(4,cell);p.setString(5,g.get("resource"));p.setString(6,g.get("operation"));p.setString(7,semantic);p.setLong(8,version);p.setString(9,digest);p.executeUpdate();}
            try(var p=c.prepareStatement("UPDATE oref.commands SET state='COMMITTED',outcome=?,boot_epoch=? WHERE command_id=?")){p.setString(1,packed(result));p.setLong(2,boot);p.setString(3,g.get("command-id"));p.executeUpdate();}
            try(var p=c.prepareStatement("INSERT INTO oref.outbox VALUES (?,?,?,?,?)")){p.setString(1,g.get("command-id"));p.setString(2,g.get("tenant"));p.setString(3,cell);p.setString(4,packed(result));p.setString(5,semantic);p.executeUpdate();}
            boundary.await("after-write");try(var s=c.createStatement();var r=s.executeQuery("SELECT (extract(epoch FROM clock_timestamp())*1000)::bigint")){r.next();require(Math.max(r.getLong(1),limitingClock.getAsLong())<Long.parseLong(g.get("expires")),"GRANT_EXPIRED_AT_COMMIT");}try{c.commit();}catch(SQLException uncertain){return map("code","UNKNOWN","id",g.get("command-id"),"reason","COMMIT_ACK_UNCERTAIN");}boundary.await("after-commit");return result;
        }
    }
    Map<String,String> receipt(String id)throws Exception{try(var c=connect();var p=c.prepareStatement("SELECT state,outcome,semantic_hash FROM oref.commands WHERE command_id=?")){check(c);p.setString(1,id);try(var r=p.executeQuery()){if(!r.next())return map("code","UNKNOWN","id",id);if(r.getString(1).equals("PREPARED"))return map("code","INCOMPLETE","id",id);var result=unpack(r.getString(2));result.put("recorded","true");return result;}}}
    Map<String,String> capabilities()throws Exception{try(var c=connect();var s=c.createStatement();var r=s.executeQuery("SELECT ssl,version,current_setting('fsync'),current_setting('synchronous_commit'),current_setting('full_page_writes'),current_user,(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user) FROM pg_stat_ssl WHERE pid=pg_backend_pid()")){require(r.next(),"PG_TLS_ROW");return map("code","OK","tls",""+r.getBoolean(1),"tls-version",r.getString(2),"fsync",r.getString(3),"synchronous-commit",r.getString(4),"full-page-writes",r.getString(5),"role",r.getString(6),"privileged",""+r.getBoolean(7));}}
    Map<String,String> connectionTests()throws Exception{
        String database=Files.readString(bootstrap.resolve("db.name")).strip(),user=Files.readString(bootstrap.resolve("db.user")).strip(),password=Files.readString(bootstrap.resolve("db.pass")).strip(),ip;
        try(var c=connect();var s=c.createStatement();var r=s.executeQuery("SELECT host(inet_server_addr())")){r.next();ip=r.getString(1);}
        var result=map("code","OK","positive","verify-full TLSv1.3");
        for(String variant:List.of("plaintext","incorrect-password","missing-password","cross-database","wrong-hostname","wrong-root")){
            var p=new Properties();p.setProperty("user",user);p.setProperty("password",password);p.setProperty("sslmode","verify-full");p.setProperty("sslrootcert",bootstrap.resolve("pg-root.pem").toString());p.setProperty("connectTimeout","3");p.setProperty("socketTimeout","5");String host="operations-state",db=database;
            switch(variant){case "plaintext":p.setProperty("sslmode","disable");break;case "incorrect-password":p.setProperty("password","INVALID-LAB-PASSWORD");break;case "missing-password":p.remove("password");break;case "cross-database":db=database.equals("oref_a")?"oref_b":"oref_a";break;case "wrong-hostname":host=ip;break;case "wrong-root":p.setProperty("sslrootcert",bootstrap.resolve("signing.cer").toString());break;default:throw new Rejected("CONNECTION_TEST_VARIANT");}
            boolean denied=false;String state="";try(var unexpected=DriverManager.getConnection("jdbc:postgresql://"+host+":5432/"+db,p)){require(unexpected.isClosed(),"UNAUTHORIZED_PG_CONNECTION:"+variant);}catch(SQLException failure){state=failure.getSQLState();denied=true;}
            require(denied,"PG_CONNECTION_NOT_DENIED:"+variant);
            require(switch(variant){case "plaintext","cross-database"->"28000".equals(state)||"42501".equals(state);case "incorrect-password"->"28P01".equals(state);case "missing-password"->"08004".equals(state)||"28P01".equals(state);default->"08006".equals(state);},"PG_UNEXPECTED_DENIAL:"+variant+":"+state);
            result.put(variant,"DENIED_"+state);
        }
        return result;
    }
}
